fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>) {
    let rows = y.len();
    let cols = x.len();

    // Create the first output matrix with the same number of rows as y and columns as x
    let mut x_grid = vec![vec![0.0; cols]; rows];
    // Create the second output matrix with the same number of rows as y and columns as x
    let mut y_grid = vec![vec![0.0; cols]; rows];

    // Fill the x_grid with the values from x
    for i in 0..rows {
        for j in 0..cols {
            x_grid[i][j] = x[j];
        }
    }

    // Fill the y_grid with the values from y
    for i in 0..rows {
        for j in 0..cols {
            y_grid[i][j] = y[i];
        }
    }

    (x_grid, y_grid)
}